import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Tree-shaking in handl","description":"","frontmatter":{"title":"Tree-shaking in handl","type":"note","date":"2026-08-24T00:00:00.000Z"},"headers":[],"relativePath":"handl/project/notes/tree-shaking.md","filePath":"vendored/handl/project/notes/tree-shaking.md"}`),a={name:`handl/project/notes/tree-shaking.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="tree-shaking-in-handl" tabindex="-1">Tree-shaking in handl <a class="header-anchor" href="#tree-shaking-in-handl" aria-label="Permalink to “Tree-shaking in handl”">​</a></h1><h2 id="two-levels-of-tree-shaking" tabindex="-1">Two levels of tree-shaking <a class="header-anchor" href="#two-levels-of-tree-shaking" aria-label="Permalink to “Two levels of tree-shaking”">​</a></h2><h3 id="_1-crate-level-cargo-features-—-done" tabindex="-1">1. Crate-level (Cargo features) — DONE <a class="header-anchor" href="#_1-crate-level-cargo-features-—-done" aria-label="Permalink to “1. Crate-level (Cargo features) — DONE”">​</a></h3><p>The <code>handl</code> facade crate is now tree-shakeable via Cargo features. All 25+ sub-crates are <code>optional = true</code> with feature flags controlling inclusion. Consumers can do:</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">handl </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> {</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> version </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">0.1</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> default-features </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> false</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> features </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> [</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">yaml</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">vm</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> }</span></span></code></pre></div><p>Core crates (<code>handl-ast</code>, <code>handl-dialect</code>, <code>handl-runtime</code>, <code>handl-source</code>) are always included. The <code>default</code> feature enables everything for backwards compatibility.</p><p>Feature groups: <code>vm</code>, <code>host</code>, <code>json</code>, <code>yaml</code>, <code>toml</code>, <code>fields</code>, <code>dialect-canonical</code>, <code>compiler</code>, <code>compiler-core</code>, <code>typecheck</code>, <code>typegen</code>, <code>resolver-core</code>, <code>resolver-memory</code>, <code>resolver-noop</code>, <code>resolver-file</code>, <code>resolver-virtual</code>, <code>lib-utils</code>, <code>lib-kv</code>, <code>lib-kv-hashmap</code>, <code>lib-platform</code>, <code>lib-platform-std</code>, <code>store</code>, <code>codebase</code>.</p><h3 id="_2-language-level-dce-pass-—-not-implemented" tabindex="-1">2. Language-level (DCE pass) — NOT IMPLEMENTED <a class="header-anchor" href="#_2-language-level-dce-pass-—-not-implemented" aria-label="Permalink to “2. Language-level (DCE pass) — NOT IMPLEMENTED”">​</a></h3><p>The handl language itself has no tree-shaking / dead code elimination. Every declared field is processed:</p><ul><li>All <code>expr:</code> fields are computed (multi-pass dependency resolution)</li><li>All <code>\${...}</code> interpolations are resolved recursively</li><li>All <code>merge:</code> fields are spread and removed</li><li>All <code>import()</code> calls are loaded and cached</li></ul><p>There is no reachability analysis — no concept of &quot;reachable&quot; vs &quot;unreachable&quot; fields. Every field in <code>$:</code> is part of the schema; every field in data is either declared or flagged as undeclared.</p><h4 id="what-exists-today-not-tree-shaking" tabindex="-1">What exists today (not tree-shaking) <a class="header-anchor" href="#what-exists-today-not-tree-shaking" aria-label="Permalink to “What exists today (not tree-shaking)”">​</a></h4><ul><li><strong>Typegen strips handl-specific keys</strong> (<code>expr</code>, <code>arg</code>, <code>merge</code>, <code>inheritable</code>, <code>mutable</code>) from output schemas — schema cleanup, not DCE</li><li><strong>Merge fields are removed</strong> after spreading — semantic behavior, not optimization</li><li><strong>Import caching</strong> — same file loaded once even if <code>import()</code> called multiple times</li></ul><h4 id="what-a-dce-pass-would-look-like" tabindex="-1">What a DCE pass would look like <a class="header-anchor" href="#what-a-dce-pass-would-look-like" aria-label="Permalink to “What a DCE pass would look like”">​</a></h4><p>A reachability pass would:</p><ol><li>Start from &quot;output fields&quot; — fields without <code>expr:</code> that appear in the final document, plus fields explicitly requested by the caller</li><li>Trace backward through <code>expr:</code> dependencies, <code>\${...}</code> interpolations, and <code>import()</code> calls</li><li>Drop everything unreachable (unused fields, unused imports, unused function values)</li></ol><p>The <code>Pass</code> trait in <code>handl-compiler-core</code> is designed for exactly this kind of addition. A custom pass slots into the pipeline without core changes:</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">let</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> pipeline </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">=</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Pipeline</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">new</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">config</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    .</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">with_pass</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">ParsePass</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    .</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">with_pass</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">ExtractPass</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    .</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">with_pass</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">DeadFieldElimPass</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">  //</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> custom — no core changes</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    .</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">with_pass</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">GeneratePass</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">);</span></span></code></pre></div><p>The pipeline docs even show this example with <code>DeadFieldElimPass</code> and <code>ConstantFoldPass</code> as placeholders (see <code>compiler-core/src/pipeline.rs</code> doc comments).</p><h4 id="challenges" tabindex="-1">Challenges <a class="header-anchor" href="#challenges" aria-label="Permalink to “Challenges”">​</a></h4><ul><li><strong>Import side effects</strong> — <code>import()</code> may load documents with function values that become available via path resolution. Determining if an import is &quot;unused&quot; requires tracing all path lookups, including those inside function bodies (which are strings evaluated lazily).</li><li><strong>Function values are data</strong> — functions are JSON objects with a <code>body</code> string. A function stored in a field might be called dynamically via <code>apply()</code>. Static reachability would need to trace through <code>apply</code> calls.</li><li><strong>Host-provided functions</strong> — the host decides which functions exist. A DCE pass can&#39;t know what side effects a host function has, so it must conservatively assume any host function call is reachable.</li><li><strong>Interpolation is recursive</strong> — <code>\${...}</code> in strings inside arrays/objects. Reachability must trace through all nested structures.</li></ul><h4 id="priority" tabindex="-1">Priority <a class="header-anchor" href="#priority" aria-label="Permalink to “Priority”">​</a></h4><p>Low — the language is designed for small configuration documents, not large programs. The overhead of unused fields is typically negligible. Tree-shaking becomes relevant if handl is used for large document graphs with many imports, where loading unused imports has real I/O cost.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};